#include <iostream>
#include <array>
int main() {
    std::array<int, 6> data{1, 2, 3, 4, 5, 6};
    int cols{3};
    std::cout << data[1 * cols + 2] << '\n';
}

#include <iostream>
#include <array>
int main() {
    std::array<int, 6> data{1, 2, 3, 4, 5, 6};
    std::array<int, 6> result{};
    for (int r = 0; r < 2; ++r) { for (int c = 0; c < 3; ++c) { result[c * 2 + r] = data[r * 3 + c]; } }
    for (int r = 0; r < 3; ++r) { std::cout << result[r * 2] << ' ' << result[r * 2 + 1] << '\n'; }
}

